corrected_code:
const { createYoga, createSchema } = require('graphql-yoga');
const { createServer } = require('node:http');
const { GraphQLError } = require('graphql');
const knex = require('knex')(require('../knexfile'));

const typeDefs = `
  type MerchantSettlement @key(fields: "id") {
    id: ID!
    payoutBatchRef: String!
    settlementAmount: Float!
    feeDeduction: Float!
    beneficiaryBankLast4: String!
    status: String!
  }

  type Query {
    _status: String
  }
`;

const resolvers = {
  MerchantSettlement: {
    __resolveReference: async (representation, context) => {
      if (!context.merchantId) {
        throw new GraphQLError('Missing authenticated merchant identifier', {
          extensions: { code: 'UNAUTHENTICATED' }
        });
      }

      // Enforce merchant ownership on the settlement record
      const settlement = await knex('settlements')
        .where({
          id: representation.id,
          merchant_id: context.merchantId
        })
        .first();

      if (!settlement) {
        throw new GraphQLError('Settlement record not found or access unauthorized', {
          extensions: { code: 'FORBIDDEN' }
        });
      }

      return settlement;
    }
  }
};

const yoga = createYoga({
  schema: createSchema({ typeDefs, resolvers }),
  context: ({ req }) => ({
    merchantId: req.headers['x-merchant-id']
  })
});

createServer(yoga).listen(5002);
